function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + (i - 5) * 20, H/2 + 20 * Math.sin(t + i), 5, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 + 100 * Math.cos(t));
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
